    self.ScrollView:InitListView(numItem, Bind(self, self.OnGetItemByIndex))
end

function CatHouseExploreRewardPopup:GetRewardsList()
    --TODO待拓展xITEM
    local result = {}
    result[1] = {}
    for i = 1, #self.listReward do
        local rewardData = {}
        rewardData.goodsId = self.listReward[i]
        rewardData.goodsNum = self.listRewardNum[i]
        table.insert(result[1], rewardData)
    end
    return result
end

function CatHouseExploreRewardPopup:OnGetItemByIndex(gridView, index)
    if index < 0 then return end
    local indexInTaskData = index + 1
    local rewards = self.rewardsData[indexInTaskData]
    local prefabPath = PREFAB_TASK_CELL
    local cell = gridView:NewListViewItem(prefabPath)
    if not IsNull(cell) then
        local cellLB = GetLuaBehaviour(cell.gameObject, PATH_LUA_CELL)
        if cellLB then
            if isNull(cellLB.Env) then cellLB:Init() end
            local cellLT = cellLB.Env
            cellLT:SetCellInfo(rewards)
        end
        KTool.SetActive(cell.gameObject, true)
    end
    return cell
end

